 "content": "def transform(grid):
    """Fill each hollow rectangular frame based on interior area parity."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    background = max(
        {value for row in out for value in row},
        key=lambda value: sum(row.count(value) for row in out),
    )
    seen = set()
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and out[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            y0 = min(y for y, _ in cells)
            y1 = max(y for y, _ in cells)
            x0 = min(x for _, x in cells)
            x1 = max(x for _, x in cells)
            border = {
                (y, x)
                for y in range(y0, y1 + 1)
                for x in range(x0, x1 + 1)
                if y in (y0, y1) or x in (x0, x1)
            }
            interior = [
                (y, x)
                for y in range(y0 + 1, y1)
                for x in range(x0 + 1, x1)
            ]
            if (cells == border and interior and
                    all(out[y][x] == background for y, x in interior)):
                fill = 7 if len(interior) % 2 else 2
                for y, x in interior:
                    out[y][x] = fill
    return out
